import re, os, sys, subprocess

def get_funcs(src):
    """Split C source into functions: list of (name, startline, endline, body_lines)."""
    lines = src.split('\n')
    funcs = []
    # find function definitions: line matching name( ... ) { at col 0 with closing brace at col 0
    func_re = re.compile(r'^(?:[A-Za-z_][A-Za-z0-9_ \t\*]*?)\b([A-Za-z_][A-Za-z0-9_]*)\s*\(')
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        m = func_re.match(line)
        if m and (line.rstrip().endswith('{') or (i+1 < n and lines[i+1].strip().endswith('{'))):
            name = m.group(1)
            # skip control statements
            if name in ('if','for','while','switch','return','sizeof'):
                i += 1; continue
            # find opening brace
            j = i
            depth = 0
            started = False
            while j < n:
                for ch in lines[j]:
                    if ch == '{':
                        depth += 1; started = True
                    elif ch == '}':
                        depth -= 1
                if started and depth == 0:
                    break
                j += 1
            funcs.append((name, i+1, j+1, lines[i:j+1]))
            i = j + 1
        else:
            i += 1
    return funcs

lock_re = re.compile(r'spin_lock(?:_irqsave(?:_nofmt)?|_irq|_bh|_irqrestore)?\s*\(\s*&?\s*([^),]+)')
bh_re = re.compile(r'spin_lock_bh\s*\(')
disable_re = re.compile(r'local_(?:bh|irq)_disable\s*\(')

def analyze(path):
    try:
        src = open(path, encoding='utf-8', errors='replace').read()
    except Exception:
        return []
    funcs = get_funcs(src)
    return funcs, src

# Identify tasklet callbacks by scanning whole file for tasklet_init/tasklet_setup/DECLARE_TASKLET
tasklet_call_re = re.compile(r'tasklet_init\s*\(\s*([^,]+),\s*([A-Za-z_][A-Za-z0-9_]*)')
tasklet_setup_re = re.compile(r'tasklet_setup\s*\(\s*([^,]+),\s*([A-Za-z_][A-Za-z0-9_]*)\s*\)')
declare_tasklet_re = re.compile(r'DECLARE_TASKLET(?:_OLD)?\s*\(\s*[^,]+,\s*([A-Za-z_][A-Za-z0-9_]*)')

napi_call_re = re.compile(r'netif_napi_add\s*\(\s*[^,]+,\s*([^,]+),\s*([A-Za-z_][A-Za-z0-9_]*)')
napi_sched_re = re.compile(r'napi_schedule(?:_irqoff|_prep)?\s*\(\s*&?\s*([A-Za-z_][A-Za-z0-9_.\->]*)')

# process-context-ish entry names
proc_re = re.compile(r'^(?:[a-z0-9_]*_open|[a-z0-9_]*_close|[a-z0-9_]*_stop|[a-z0-9_]*_start|[a-z0-9_]*_probe[0-9]*|[a-z0-9_]*_remove|[a-z0-9_]*_init\b|[a-z0-9_]*_suspend|[a-z0-9_]*_resume|[a-z0-9_]*_set_mac_address|[a-z0-9_]*_ethtool[a-z0-9_]*|[a-z0-9_]*_ioctl|[a-z0-9_]*_work|[a-z0-9_]*_dwork|[a-z0-9_]*_netdev_ops|[a-z0-9_]*_down|[a-z0-9_]*_up|[a-z0-9_]*_config[a-z0-9_]*|[a-z0-9_]*_connect|[a-z0-9_]*_disconnect|[a-z0-9_]*_fw[a-z0-9_]*|[a-z0-9_]*_timeout)$')

def base_lock(expr):
    expr = expr.strip().rstrip(')')
    # strip irqsave second arg
    return expr.strip()

results = []
files = sys.argv[1:]
for path in files:
    try:
        src = open(path, encoding='utf-8', errors='replace').read()
    except Exception:
        continue
    tcall = set()
    for m in tasklet_call_re.finditer(src): tcall.add(m.group(2))
    for m in tasklet_setup_re.finditer(src): tcall.add(m.group(2))
    for m in declare_tasklet_re.finditer(src): tcall.add(m.group(1))
    npoll = set()
    for m in napi_call_re.finditer(src):
        npoll.add(m.group(2).strip())
    if not tcall and not npoll:
        continue
    funcs, _ = analyze(path)
    fmap = {}
    for name, s, e, body in funcs:
        fmap.setdefault(name, []).append((s, e, body))
    # collect lock usage per function
    func_locks = {}
    for name, s, e, body in funcs:
        if name not in func_locks:
            func_locks[name] = []
        for idx, l in enumerate(body):
            for m in lock_re.finditer(l):
                kind = 'plain'
                if '_bh' in m.group(0): kind = 'bh'
                elif 'irqsave' in m.group(0): kind = 'irqsave'
                elif '_irq' in m.group(0): kind = 'irq'
                func_locks[name].append((s+idx, kind, m.group(1).strip()))
            if disable_re.search(l):
                func_locks[name].append((s+idx, 'disable', 'local_bh_disable'))
    # tasklet side locks
    tasklet_locks = {}   # lock -> (func, line, kind)
    for cb in tcall:
        for (s, e, body) in fmap.get(cb, []):
            for idx, l in enumerate(body):
                for m in lock_re.finditer(l):
                    kind = 'plain' if '_bh' not in m.group(0) and 'irq' not in m.group(0) else ('bh' if '_bh' in m.group(0) else 'irqsave' if 'irqsave' in m.group(0) else 'irq')
                    tasklet_locks.setdefault(m.group(1).strip(), []).append((cb, s+idx, kind))
    napi_locks = {}
    for cb in npoll:
        for (s, e, body) in fmap.get(cb, []):
            for idx, l in enumerate(body):
                for m in lock_re.finditer(l):
                    kind = 'plain' if '_bh' not in m.group(0) and 'irq' not in m.group(0) else ('bh' if '_bh' in m.group(0) else 'irqsave' if 'irqsave' in m.group(0) else 'irq')
                    napi_locks.setdefault(m.group(1).strip(), []).append((cb, s+idx, kind))
    if not tasklet_locks and not napi_locks:
        continue
    # process-side plain locks sharing the same expression
    for lock, tinfo in list(tasklet_locks.items()) + list(napi_locks.items()):
        for name, s, e, body in funcs:
            if name in tcall or name in npoll: continue
            isproc = bool(proc_re.match(name))
            for (line, kind, lexpr) in func_locks[name]:
                if lexpr == lock and kind == 'plain':
                    results.append((path, lock, 'tasklet' if lock in tasklet_locks else 'napi', name, line, isproc, tinfo))

for r in results:
    print('|'.join(str(x) for x in r[:6]), '#', r[6] if len(r)>6 else '')
